// Data loading for the Observatory. Every file comes from website/public/data (generated by
// `make web-data` from the committed reports/session10/observatory export) and is parsed by its
// zod schema before use. Gzipped JSON is decompressed in the browser (DecompressionStream), so
// no server configuration is needed. Missing or invalid files raise DataError with the path and
// the fix, which the UI shows instead of a blank viewer.
import { z } from "zod";
import { Clip, Clouds, Denoise, Findings, MeshTable, Registry, Verification } from "./schema";

const BASE = `${import.meta.env.BASE_URL}`;

export class DataError extends Error {
  constructor(public path: string, message: string) {
    super(`${path}: ${message}`);
  }
}

async function readJson(path: string, optional = false): Promise<unknown | null> {
  const url = `${BASE}${path}`;
  let res: Response;
  try {
    res = await fetch(url);
  } catch (e) {
    throw new DataError(path, `network error (${(e as Error).message})`);
  }
  if (!res.ok) {
    if (optional && res.status === 404) return null;
    throw new DataError(path, `HTTP ${res.status}. Run \`make web-data\` to generate the site data.`);
  }
  if (path.endsWith(".gz")) {
    const head = new Uint8Array(await res.clone().arrayBuffer()).slice(0, 2);
    const gz = head[0] === 0x1f && head[1] === 0x8b;
    const body = gz ? res.body!.pipeThrough(new DecompressionStream("gzip")) : res.body!;
    return JSON.parse(await new Response(body).text());
  }
  const text = await res.text();
  if (text.trimStart().startsWith("<")) {
    if (optional) return null;
    throw new DataError(path, "not found (the server returned HTML). Run `make web-data`.");
  }
  return JSON.parse(text);
}

const cache = new Map<string, Promise<unknown>>();

function load<T>(path: string, schema: z.ZodType<T>): Promise<T> {
  if (!cache.has(path)) {
    cache.set(path, readJson(path).then((raw) => {
      const r = schema.safeParse(raw);
      if (!r.success) {
        throw new DataError(path, `schema check failed: ${r.error.issues.slice(0, 3)
          .map((i) => `${i.path.join(".")}: ${i.message}`).join("; ")}`);
      }
      return r.data;
    }));
  }
  return cache.get(path) as Promise<T>;
}

export const dataUrl = (file: string): string => `${BASE}data/${file}`;
export const loadRegistry = () => load("data/registry.json", Registry);
export const loadFindings = () => load("data/findings.json", Findings);
export const loadClip = (id: string) => load(`data/clips/${id}.json.gz`, Clip);
export const loadDenoise = (file: string) => load(`data/${file}`, Denoise);
export const loadClouds = (file: string) => load(`data/${file}`, Clouds);
export const loadMeshTable = () => load("assets/meshes.json", MeshTable);

export async function loadVerification() {
  const raw = await readJson("data/viewer_verification.json", true);
  if (raw === null) return null;
  return Verification.parse(raw);
}

export async function loadMeshBlob(): Promise<ArrayBuffer> {
  const res = await fetch(`${BASE}assets/meshes.bin`);
  if (!res.ok) {
    throw new DataError("assets/meshes.bin", `HTTP ${res.status}. Run \`make web-assets\` (D-090).`);
  }
  return res.arrayBuffer();
}
